	count(if(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 90 and call_mode='manual' and called_phone_social_relations='friend' and is_valid_contact='yes',1,null)) / count(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 90) as percent_true_call_mode_is_manual_called_phone_social_relations_is_friend_is_valid_contact_is_yes_90d,
	count(if(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 90 and call_mode='yuce' and called_phone_social_relations='self' and is_valid_contact='no',1,null)) as num_true_call_mode_is_yuce_called_phone_social_relations_is_self_is_valid_contact_is_no_90d,
	count(if(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 90 and call_mode='yuce' and called_phone_social_relations='friend' and is_valid_contact='no',1,null)) / count(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 90) as percent_true_call_mode_is_yuce_called_phone_social_relations_is_friend_is_valid_contact_is_no_90d,
	count(if(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 90 and call_mode='yuce' and called_phone_social_relations='family' and is_valid_contact='no',1,null)) as num_true_call_mode_is_yuce_called_phone_social_relations_is_family_is_valid_contact_is_no_90d,
	count(if(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 90 and call_mode='manual' and called_phone_social_relations='family' and is_valid_contact='yes',1,null)) as num_true_call_mode_is_manual_called_phone_social_relations_is_family_is_valid_contact_is_yes_90d
 from (select uid,mdl_dte from ${pdm_risk}.pdm_risk_dh_model_sample_yesterday where ds = '${bizdate}') smp_dt
 left join (select uid,call_time,
case when call_mode = 0 then 'manual' when call_mode = 1 then 'ai'  else 'yuce' end as call_mode,
case when called_phone_social_relations in ('本人','客户本人') then 'self' when called_phone_social_relations in ('家人','子女','兄弟姐妹','父母',
'夫妻','配偶','父亲','母亲') then 'family' else 'friend' end as called_phone_social_relations,
case when is_valid_contact =1 then 'yes' else 'no' end as is_valid_contact,
case when followup_phone_code in ('ALPA','B','XSHK','NPWJ','YQDK','PTP','C','HKDG','A','CHAT','OPTP') 
           or (followup_phone_code in ('无','') and followup_action_code in ('actionCode_3','actionCode_4','actionCode_5','actionCode_6')) then 'yyxh' --意向还款
    when followup_phone_code in ('WFJT','LXBS','LIMIT','BUSY','NULL','G','OFF','NOSE','NZG','YYXX','STOP','CUTA','F','NOASA','WFSB','NCC','NM','KJCS','H',
    'NOAS','ZLWSB','LOOO','FRRS','HRWJT','YCGD','YYLY','YJJD','JJZG','LIMI','SLXF') 
           or (followup_phone_code in ('无','') and followup_action_code in ('actionCode_8','actionCode_9','actionCode_10','actionCode_11','actionCode_18')) then 'wfjt'  -- 无法接通
   when followup_phone_code in ('NPJH','RTP','INSY','NPZJ','CLR','CDLT','OUGT') 
           or (followup_phone_code in ('无','') and followup_action_code in ('actionCode_2','actionCode_7','actionCode_19')) then 'jjhk' --拒绝还款
   when followup_phone_code in ('MESS','D','C','WCNHK','YM','RS','LMS') then 'yjt' --已接通
   when followup_phone_code in ('TS','TCZ','RHWR','QACL','TSCL','QACL','DISP')  
           or (followup_phone_code in ('无','') and followup_action_code in ('actionCode_1','actionCode_15','actionCode_16','actionCode_20')) then 'tskh'  --投诉客户
  else 'other' end as followup_code
from dwt.dwt_collection_call_record_detail_di where ds between to_char(date(add_months(to_date('${bizdate}','yyyymmdd'),-6)),'yyyymmdd') and to_char(date(date_add(to_date('${bizdate}','yyyymmdd'),-1)),'yyyymmdd')
and uid is not null and call_time is not null 
) atom_dt
 on smp_dt.uid=atom_dt.uid
and to_date(atom_dt.call_time) >= date_add(to_date(smp_dt.mdl_dte), -180) 
and to_date(atom_dt.call_time) < to_date(smp_dt.mdl_dte)
group by smp_dt.uid, smp_dt.mdl_dte
;
